// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/streams/preview", wrapper.PreviewStream)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams", wrapper.ListStreams)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/streams", wrapper.CreateStream)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams/{streamId}", wrapper.GetStream)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/streams/{streamId}/collections", wrapper.StartCollection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams/{streamId}/collections/latest", wrapper.GetLatestCollection)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/collection-jobs/{jobId}/retry", wrapper.RetryCollection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams/{streamId}/chat-messages", wrapper.ListChatMessages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams/{streamId}/chat-search", wrapper.SearchChatMessages)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/streams/{streamId}/chat-activity", wrapper.GetChatActivity)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reservations", wrapper.ListReservations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/reservations", wrapper.CreateReservation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/reservations/{reservationId}", wrapper.GetReservation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/reservations/{reservationId}/cancel", wrapper.CancelReservation)

	return m
}

